def lps(s):
    n = len(s)
    # Create a 2D array to store the longest palindromic subsequence
    dp = [[0 for _ in range(n)] for _ in range(n)]
    # Initialize the first row and column to 0
    for i in range(n):
        dp[i][i] = 1
    # Fill the rest of the matrix
    for i in range(1, n):
        for j in range(0, i):
            if s[i] == s[j] and (j - i + 1) in [0, i - 1]:
                dp[i][j] = 1
                # Update the longest palindromic subsequence
                if dp[i][j] > dp[i][j - 1]:
                    dp[i][j] = dp[i][j - 1] + 2
    # Find the longest palindromic subsequence
    max_len = 0
    max_sub = []
    for i in range(n):
        for j in range(i, n):
            if dp[i][j] > max_len:
                max_len = dp[i][j]
                max_sub = [s[i:j+1]]
    return max_sub


